import { readFileSync } from 'node:fs';

const DB_URL = new URL('../data/users.json', import.meta.url);

export function loadUsers() {
  return JSON.parse(readFileSync(DB_URL, 'utf8'));
}

export function fullName(user) {
  return user.name;
}

export function byFullName(users, wanted) {
  return users.find((user) => user.name === wanted);
}

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { byFullName, fullName, loadUsers } from '../src/users.js';

test('loads every user record', () => {
  assert.equal(loadUsers().length, 3);
});

test('fullName renders the display name', () => {
  assert.deepEqual(loadUsers().map(fullName), [
    'Ada Lovelace',
    'Grace Hopper',
    'Annie Easley',
  ]);
});

test('byFullName finds a user by display name', () => {
  assert.equal(byFullName(loadUsers(), 'Grace Hopper').email, 'grace@example.com');
});

import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';

const root = process.cwd();

// 1) The data moved to the target shape with no record stranded.
const records = JSON.parse(readFileSync(join(root, 'data/users.json'), 'utf8'));
assert.ok(Array.isArray(records), 'data/users.json must stay a JSON array');
assert.equal(records.length, 3, 'all three records must survive the migration');
const expected = new Map([
  ['ada@example.com', ['Ada', 'Lovelace']],
  ['grace@example.com', ['Grace', 'Hopper']],
  ['annie@example.com', ['Annie', 'Easley']],
]);
for (const record of records) {
  assert.ok(record && typeof record === 'object', 'each record must stay an object');
  assert.ok(!('name' in record), `record ${record.id} still carries the flat name field`);
  const want = expected.get(record.email);
  assert.ok(want, `record ${record.id} lost or changed its email`);
  assert.equal(record.profile?.first, want[0], `record ${record.id} must keep its first name exactly`);
  assert.equal(record.profile?.last, want[1], `record ${record.id} must keep its last name exactly`);
}
console.log('SCHEMAMIG_ORACLE data intact');

// 2) The accessors read the new shape - a pure nested record, no flat fallback.
const users = await import(pathToFileURL(join(root, 'src/users.js')).href);
assert.equal(
  users.fullName({ profile: { first: 'Test', last: 'User' } }),
  'Test User',
  'fullName must read profile.first and profile.last',
);
assert.equal(
  users.byFullName([{ profile: { first: 'Grace', last: 'Hopper' }, email: 'x' }], 'Grace Hopper')?.email,
  'x',
  'byFullName must match display names on the new shape',
);
console.log('SCHEMAMIG_ORACLE accessors migrated');

// 3) Contract landed: no flat-shape read remains in the accessor module.
const accessorSource = readFileSync(join(root, 'src/users.js'), 'utf8');
assert.ok(
  !/\.name\b|\[["']name["']\]/.test(accessorSource),
  'src/users.js still reads the flat name field',
);
console.log('SCHEMAMIG_ORACLE contract complete');

// 4) The suite is green on the migrated tree, and the seeded test file survives.
readFileSync(join(root, 'tests/users.test.mjs'));
function runSuite(cwd) {
  try {
    execFileSync(process.execPath, ['--test'], { cwd, stdio: 'pipe', timeout: 30000 });
    return 0;
  } catch (err) {
    return typeof err.status === 'number' ? err.status : 1;
  }
}
assert.equal(runSuite(root), 0, 'the suite must be green after the migration');
console.log('SCHEMAMIG_ORACLE suite green');
console.log('SCHEMAMIG_ORACLE done');
